#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Creates the store credentials used by .github/workflows/release.yml, sets them as GitHub secrets
# and keeps a local copy in apps/extension/.env.submit (git-ignored) for `wxt submit --dry-run`.
# Run from the repository root: bash scripts/setup-release-secrets.sh

ENV_FILE="apps/extension/.env.submit"
TOTAL_STAGES=6

cd "$(dirname "$0")/.."

# clean_path PATH undoes what dragging a file into the terminal adds: trailing space, escaped spaces, quotes, ~.
clean_path() {
  local path="${1%"${1##*[![:space:]]}"}"
  path="${path//\\ / }"
  path="${path#\'}"; path="${path%\'}"
  printf '%s' "${path/#\~/$HOME}"
}

banner "Optizzz : secrets de publication Chrome et Firefox"

# check_amo_credentials prints the HTTP status AMO answers to a signed, read-only request for the add-on.
check_amo_credentials() {
  FIREFOX_JWT_ISSUER="$FIREFOX_JWT_ISSUER" FIREFOX_JWT_SECRET="$FIREFOX_JWT_SECRET" node --input-type=module -e '
    import { createHmac, randomUUID } from "node:crypto";
    const b64 = (o) => Buffer.from(JSON.stringify(o)).toString("base64url");
    const now = Math.floor(Date.now() / 1000);
    const unsigned = `${b64({ alg: "HS256", typ: "JWT" })}.${b64({ iss: process.env.FIREFOX_JWT_ISSUER, jti: randomUUID(), iat: now, exp: now + 60 })}`;
    const signature = createHmac("sha256", process.env.FIREFOX_JWT_SECRET).update(unsigned).digest("base64url");
    const res = await fetch("https://addons.mozilla.org/api/v5/addons/addon/optizzz@achaak.github.io/", {
      headers: { Authorization: `JWT ${unsigned}.${signature}` },
    });
    console.log(res.status);
  '
}

# ──────────────────────────────────────────────────────────────────────────
stage "Chrome : identifiants de l'extension"
say "Deux identifiants publics : celui de l'extension et celui de l'éditeur."
open_url "https://chrome.google.com/webstore/devconsole"
step "Dans la console développeur, l'URL devient …/devconsole/<ID d'éditeur>/… : copiez cet ID."
note "Il est aussi sur la page Compte, rubrique « Publisher ID »."
ask CHROME_PUBLISHER_ID "ID d'éditeur :"
step "Ouvrez la fiche Optizzz : l'ID de l'extension est dans l'URL (32 lettres)."
note "Celui de la fiche publiée : goeifkbimepccacjfkkmhjmhgoiigjpl (Entrée sans rien saisir le garde)."
ask CHROME_EXTENSION_ID "ID de l'extension :"
CHROME_EXTENSION_ID="${CHROME_EXTENSION_ID:-goeifkbimepccacjfkkmhjmhgoiigjpl}"
write_env CHROME_PUBLISHER_ID "$CHROME_PUBLISHER_ID"
write_env CHROME_EXTENSION_ID "$CHROME_EXTENSION_ID"
set_secret CHROME_PUBLISHER_ID "$CHROME_PUBLISHER_ID"
set_secret CHROME_EXTENSION_ID "$CHROME_EXTENSION_ID"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Chrome : compte de service Google Cloud"
say "L'API Chrome Web Store s'authentifie avec un compte de service et sa clé JSON."
note "Guide officiel : https://developer.chrome.com/docs/webstore/service-accounts"
open_url "https://console.cloud.google.com/projectcreate"
step "Créez un projet (ex. « optizzz-release ») ou choisissez-en un existant."
pause "Projet prêt ? Entrée pour activer l'API."
open_url "https://console.cloud.google.com/apis/library/chromewebstore.googleapis.com"
step "Vérifiez que le projet choisi en haut est le bon, puis cliquez « Activer »."
pause "API activée ? Entrée pour créer le compte de service."
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create"
step "Nom : optizzz-release. Aucun rôle ni accès à accorder : « OK » / « Terminé »."
step "Ouvrez le compte créé → onglet « Clés » → « Ajouter une clé » → « Créer une clé » → JSON."
step "Le navigateur télécharge un fichier .json : gardez-le hors du dépôt."
warn "Si « Créer une clé » est refusé, une règle d'organisation (iam.disableServiceAccountKeyCreation) l'interdit sur ce projet."
ask CHROME_SERVICE_ACCOUNT_JSON "Chemin du fichier JSON téléchargé (glissez-le ici) :"
CHROME_SERVICE_ACCOUNT_JSON=$(clean_path "$CHROME_SERVICE_ACCOUNT_JSON")
until [[ -f "$CHROME_SERVICE_ACCOUNT_JSON" ]]; do
  warn "Fichier introuvable : $CHROME_SERVICE_ACCOUNT_JSON"
  ask CHROME_SERVICE_ACCOUNT_JSON "Chemin du fichier JSON :"
  CHROME_SERVICE_ACCOUNT_JSON=$(clean_path "$CHROME_SERVICE_ACCOUNT_JSON")
done
CHROME_SERVICE_ACCOUNT_CLIENT_EMAIL=$(node -p 'require(process.argv[1]).client_email' "$CHROME_SERVICE_ACCOUNT_JSON")
CHROME_SERVICE_ACCOUNT_PRIVATE_KEY=$(node -p 'require(process.argv[1]).private_key.trim()' "$CHROME_SERVICE_ACCOUNT_JSON")
say "Compte de service : $CHROME_SERVICE_ACCOUNT_CLIENT_EMAIL"
write_env CHROME_SERVICE_ACCOUNT_JSON "$CHROME_SERVICE_ACCOUNT_JSON"
write_env CHROME_SERVICE_ACCOUNT_CLIENT_EMAIL "$CHROME_SERVICE_ACCOUNT_CLIENT_EMAIL"
# .env.submit holds the key on one line, newlines escaped inside double quotes (dotenv expands them).
write_env CHROME_SERVICE_ACCOUNT_PRIVATE_KEY "\"${CHROME_SERVICE_ACCOUNT_PRIVATE_KEY//$'\n'/\\n}\""
set_secret CHROME_SERVICE_ACCOUNT_CLIENT_EMAIL "$CHROME_SERVICE_ACCOUNT_CLIENT_EMAIL"
set_secret CHROME_SERVICE_ACCOUNT_PRIVATE_KEY "$CHROME_SERVICE_ACCOUNT_PRIVATE_KEY"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Chrome : autoriser le compte de service sur la console développeur"
say "Sans ce lien, Google refuse au compte de service de publier Optizzz."
open_url "https://chrome.google.com/webstore/devconsole/$CHROME_PUBLISHER_ID"
step "Menu de gauche → « Compte » (« Account ») → rubrique « Service accounts »."
step "Ajoutez : $CHROME_SERVICE_ACCOUNT_CLIENT_EMAIL"
step "Enregistrez."
pause "Compte de service ajouté ? Entrée pour passer à Firefox."

# ──────────────────────────────────────────────────────────────────────────
stage "Firefox : clés API d'AMO"
say "L'identifiant de l'extension est fixe : optizzz@achaak.github.io."
FIREFOX_EXTENSION_ID="optizzz@achaak.github.io"
write_env FIREFOX_EXTENSION_ID "$FIREFOX_EXTENSION_ID"
set_secret FIREFOX_EXTENSION_ID "$FIREFOX_EXTENSION_ID"
open_url "https://addons.mozilla.org/developers/addon/api/key/"
step "Connectez-vous avec le compte qui possède Optizzz."
step "« Générer de nouveaux identifiants » (ou les régénérer : les anciens cessent de marcher)."
step "Copiez l'« Émetteur JWT » (user:12345:678)."
ask FIREFOX_JWT_ISSUER "Émetteur JWT :"
step "Copiez le « Secret JWT » (il ne s'affiche qu'une fois)."
ask_secret FIREFOX_JWT_SECRET "Secret JWT (saisie masquée) :"
until amo_status=$(check_amo_credentials) && [[ "$amo_status" == 200 ]]; do
  warn "AMO refuse ces clés (réponse ${amo_status:-sans réseau}) : secret mal copié ou clés régénérées depuis."
  confirm "Les saisir de nouveau ?" || break
  ask FIREFOX_JWT_ISSUER "Émetteur JWT :"
  ask_secret FIREFOX_JWT_SECRET "Secret JWT (saisie masquée) :"
done
[[ "$amo_status" == 200 ]] && printf '  %s✓ clés acceptées par AMO%s\n' "$GREEN" "$RESET"
write_env FIREFOX_JWT_ISSUER "$FIREFOX_JWT_ISSUER"
write_env FIREFOX_JWT_SECRET "$FIREFOX_JWT_SECRET"
set_secret FIREFOX_JWT_ISSUER "$FIREFOX_JWT_ISSUER"
set_secret FIREFOX_JWT_SECRET "$FIREFOX_JWT_SECRET"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Vérifier l'authentification (sans rien publier)"
say "Construit les zips puis lance wxt submit --dry-run avec .env.submit : il se connecte aux"
say "deux stores sans rien envoyer."
if confirm "Lancer la vérification maintenant (environ une minute) ?"; then
  if pnpm zip >/dev/null && pnpm zip:firefox >/dev/null && (cd apps/extension && pnpm exec wxt submit --dry-run \
    --chrome-zip .output/*-chrome.zip --chrome-api-version v2 \
    --firefox-zip .output/*-firefox.zip --firefox-sources-zip .output/*-sources.zip); then
    printf '  %s✓ authentification acceptée par les deux stores%s\n' "$GREEN" "$RESET"
  else
    warn "La vérification a échoué : relisez le message ci-dessus, corrigez puis relancez l'assistant."
    SKIPPED+=("vérification wxt submit --dry-run en échec")
  fi
else
  SKIPPED+=("vérification : wxt submit --dry-run dans apps/extension (voir docs/publication.md)")
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Publier la version courante"
version=$(node -p 'require("./apps/extension/package.json").version')
say "La version $version n'a pas encore de tag : le workflow Release peut la publier."
say "Il faut que le nouveau release.yml (déclenchement manuel) soit déjà poussé sur main."
warn "Publier envoie la version aux deux stores : c'est irréversible."
if git ls-remote --exit-code --tags origin "refs/tags/v$version" >/dev/null 2>&1; then
  note "v$version est déjà taguée : rien à publier. La prochaine version partira seule."
elif ! git fetch -q origin main || ! git show origin/main:.github/workflows/release.yml | grep -q workflow_dispatch; then
  note "release.yml n'est pas encore à jour sur origin/main : poussez-le, puis lancez"
  note "  gh workflow run release.yml"
  SKIPPED+=("publier v$version : gh workflow run release.yml (après le push)")
elif confirm "Publier v$version maintenant sur Chrome et Firefox ?"; then
  gh workflow run release.yml --ref main
  printf "  %s✓ workflow lancé%s : gh run watch, ou l'onglet Actions du dépôt\n" "$GREEN" "$RESET"
else
  SKIPPED+=("publier v$version : gh workflow run release.yml")
fi
pause

finish
